insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_facilities','facilities','noun','the buildings, rooms and services that are provided for people to use, such as toilets, a café or a swimming pool','[{"senseId":"facilities_1","meaning":"the buildings, rooms and services that are provided for people to use, such as toilets, a café or a swimming pool","acceptedParaphrases":["amenities for guests","buildings and services for visitors"],"masteryContexts":[{"contextId":"u5_41_facilities_meaning","text":"The sports centre has excellent facilities, including a pool, a climbing wall and changing rooms.","meaning":"the buildings and services provided for people to use","wrongMeanings":["the staff and managers employed to look after people","the payments and prices charged for services to people","the rules and notices displayed for people to read"]},{"contextId":"u5_41_facilities_paraphrase","text":"Parents of young children often choose a campsite with good toilet and washing facilities.","meaning":"the rooms and services that are provided for the use of visitors","wrongMeanings":["the groups and clubs that are organised by the visitors","the stories and photographs that are collected by visitors","the maps and signs that are written for the visitors"]}],"situationDistractors":["The mayor cut a ribbon to open the new bridge over the river.","A group of students sat on the grass and sketched the old castle.","The postman delivered a parcel to the cottage at the end of the lane.","A cold wind blew across the harbour and the fishermen pulled on their coats.","The museum closed early on Mondays so that the staff could clean the galleries.","Two cyclists stopped at the crossroads to read the signpost."],"gapDistractors":[{"contextId":"u5_41_facilities_gap_1","answer":"facilities","wrong":["souvenirs","timetables","brochures"]},{"contextId":"u5_41_facilities_gap_2","answer":"facilities","wrong":["photographs","tickets","guidebooks"]},{"contextId":"u5_41_facilities_gap_3","answer":"facilities","wrong":["rainstorms","languages","postcards"]}],"spellingErrors":["facilitys","facilites","facillities","faciliteis","facilties","fasilities"],"masteryPassages":[{"passageId":"u5_41_facilities_passage_1","contextId":"u5_41_facilities_gap_1","text":"The new youth hostel stands beside a lake and is surrounded by pine forests. Although the dormitories are simple, the ____ are excellent, with a large kitchen, a laundry and a games room.","answer":"facilities"},{"passageId":"u5_41_facilities_passage_2","contextId":"u5_41_facilities_gap_2","text":"Disabled visitors need to know in advance whether a park can offer ramps, wide paths and accessible toilets. The website lists all of the ____ and shows them on a simple map.","answer":"facilities"}],"contextDependentParaphrases":[],"wrongParaphrases":["complaints from guests","tickets for guests","reviews by guests"],"misleadingDistractors":["the money that visitors pay to enter an attraction","the people who work at a visitor centre","the rules that visitors must follow on a site"],"teacherNote":"Normally plural in this sense: the buildings, rooms and services provided for users (toilets, a café, a pool). It is not the same as equipment, which is the physical items needed for an activity."}]'::jsonb,'[]'::jsonb,'["sports facilities","excellent facilities","facilities for visitors"]'::jsonb,'live'),
('vocab_equipment_5','equipment','noun','the items and tools that people need in order to do a particular sport or activity','[{"senseId":"equipment_5_1","meaning":"the items and tools that people need in order to do a particular sport or activity","acceptedParaphrases":["kit","items needed for an activity"],"masteryContexts":[{"contextId":"u5_42_equipment_5_meaning","text":"Hire shops in the mountain village rent out skis, boots and other winter sports equipment by the day.","meaning":"the items needed for a particular sport or activity","wrongMeanings":["the places where a particular sport or activity is held","the rules written for a particular sport or activity","the people trained for a particular sport or activity"]},{"contextId":"u5_42_equipment_5_paraphrase","text":"Climbing a rock face without the right equipment is extremely dangerous, however strong you are.","meaning":"the ropes, tools and clothing that people need for an activity","wrongMeanings":["the maps, books and photographs that people take of an activity","the guides, drivers and cooks that people hire for an activity","the tickets, passes and receipts that people keep from an activity"]}],"situationDistractors":["A waiter carried a tray of cold drinks across the terrace.","The tour leader read out the names of the people in the group.","Heavy rain filled the streets of the old town with puddles.","Two students waited at the harbour wall for the ferry to the island.","The market closes at five, so the traders pack away their stalls early.","Fog hung over the valley until the middle of the morning."],"gapDistractors":[{"contextId":"u5_42_equipment_5_gap_1","answer":"equipment","wrong":["scenery","weather","traffic"]},{"contextId":"u5_42_equipment_5_gap_2","answer":"equipment","wrong":["rainfall","scenery","traffic"]},{"contextId":"u5_42_equipment_5_gap_3","answer":"equipment","wrong":["sunshine","traffic","information"]}],"spellingErrors":["equipement","equipmant","ekwipment","equiptment","equipmet","equipmment"],"wordFamilyForms":[{"form":"equipment","partOfSpeech":"noun","example":"The adventure camp provides all the equipment that beginners need on the climbing wall.","pedagogicallyUseful":true},{"form":"equip","partOfSpeech":"verb","example":"The centre plans to equip every instructor with a radio and a first-aid kit.","pedagogicallyUseful":true,"altExample":"The government decided to equip all rescue teams with satellite phones."},{"form":"equipped","partOfSpeech":"adjective","example":"Each cabin is fully equipped with a stove, a fridge and warm blankets.","pedagogicallyUseful":true,"altExample":"The expedition was well equipped for the cold, with tents, stoves and thick jackets."}],"masteryPassages":[{"passageId":"u5_42_equipment_5_passage_1","contextId":"u5_42_equipment_5_gap_1","text":"The expedition leader spread everything out on the floor of the hut and counted it twice. Ropes, tents, stoves and radios were all there, so the team felt confident that their ____ was complete.","answer":"equipment"},{"passageId":"u5_42_equipment_5_passage_2","contextId":"u5_42_equipment_5_gap_2","text":"Beginners at the sailing school do not need to buy anything before the first lesson. The school provides life jackets, wetsuits and all the other ____ that students need on the water.","answer":"equipment"}],"contextDependentParaphrases":[],"wrongParaphrases":["luggage","souvenirs","fuel"],"misleadingDistractors":["the money paid to use a sports centre","the instructions that explain how to play a sport","the people who help visitors during an activity"],"teacherNote":"Unit 5 item (equipment_5), separate from the Unit 2 and Unit 4 equipment items; shares only the lexical spelling list. Uncountable: no “an equipment” or “equipments”; use “a piece of equipment”. Facilities are buildings and services, whereas equipment is the physical items needed for an activity."}]'::jsonb,'["equip","equipped"]'::jsonb,'["camping equipment","climbing equipment","a piece of equipment"]'::jsonb,'live'),
('vocab_location','location','noun','the place or position where something is found or situated','[{"senseId":"location_1","meaning":"the place or position where something is found or situated","acceptedParaphrases":["position","spot"],"masteryContexts":[{"contextId":"u5_43_location_meaning","text":"The new visitor centre has a perfect location at the foot of the mountain, only five minutes from the car park.","meaning":"the place where something is situated","wrongMeanings":["the person who is responsible for a place","the time at which something is opened","the reason why something is built"]},{"contextId":"u5_43_location_paraphrase","text":"Because of its remote location, the island has no bridge and can only be reached by boat.","meaning":"the position of a place in relation to other places","wrongMeanings":["the size of a place compared with other places","the age of a place in relation to other places","the cost of a place compared with other places"]}],"situationDistractors":["The conductor tapped his baton, and the orchestra began to play.","Two children shared an umbrella as they walked to school.","The baker sold out of bread before nine o’clock.","A little girl pointed at a rainbow over the roofs of the village.","Students collected shells along the shore and sorted them into boxes.","The librarian stamped the date on the inside cover of each book."],"gapDistractors":[{"contextId":"u5_43_location_gap_1","answer":"location","wrong":["collection","invitation","competition"]},{"contextId":"u5_43_location_gap_2","answer":"location","wrong":["decoration","reputation","temperature"]},{"contextId":"u5_43_location_gap_3","answer":"location","wrong":["price","menu","timetable"]}],"spellingErrors":["locaton","lokation","locashon","loccation","locatoin","lacation"],"wordFamilyForms":[{"form":"location","partOfSpeech":"noun","example":"The tourist board has chosen a central location for the new information office.","pedagogicallyUseful":true},{"form":"locate","partOfSpeech":"verb","example":"Visitors can use the map in the app to locate the nearest pharmacy.","pedagogicallyUseful":true,"altExample":"Rescue teams used a satellite signal to locate the missing walkers."},{"form":"located","partOfSpeech":"adjective","example":"The campsite is located beside a quiet lake, about ten minutes from the village.","pedagogicallyUseful":true,"altExample":"The visitor centre is located on the main square, opposite the cathedral."}],"masteryPassages":[{"passageId":"u5_43_location_passage_1","contextId":"u5_43_location_gap_1","text":"Before buying the old farmhouse, the family walked around the village, talked to the neighbours and checked the bus times. They were delighted with the ____, because the beach, the shops and the school were all within walking distance.","answer":"location"},{"passageId":"u5_43_location_passage_2","contextId":"u5_43_location_gap_2","text":"The writer of the guidebook visited every restaurant in town. He praised the food at the harbour café, but he thought that its ____ next to a noisy car park spoilt the evening.","answer":"location"}],"contextDependentParaphrases":[],"wrongParaphrases":["schedule","budget","distance"],"misleadingDistractors":["a long journey made by sea or by air","the number of people who live in a particular area","the time of year when most visitors arrive"],"teacherNote":"The place or position where something is found. Not the same as destination, which is the place a traveller is going to."}]'::jsonb,'["locate","located"]'::jsonb,'["a central location","a remote location","the exact location"]'::jsonb,'live'),
('vocab_obtain','obtain','verb','to get something, especially by making an effort or by following an official process','[{"senseId":"obtain_1","meaning":"to get something, especially by making an effort or by following an official process","acceptedParaphrases":["acquire","get hold of"],"masteryContexts":[{"contextId":"u5_44_obtain_meaning","text":"Foreign visitors can obtain a tourist visa online in less than ten minutes.","meaning":"to get something through an official process","wrongMeanings":["to give something back after an official process","to lose something because of an official process","to send something through an official process"]},{"contextId":"u5_44_obtain_paraphrase","text":"It was difficult to obtain accurate information about the ferry times, because every website gave a different answer.","meaning":"to succeed in getting something that is difficult to find","wrongMeanings":["to fail to understand something that is difficult to read","to decide to sell something that is difficult to replace","to agree to repair something that is difficult to lift"]}],"situationDistractors":["A seagull landed on the railing and watched the children eat their chips.","The farmer drove his tractor slowly along the narrow road.","The choir rehearsed in the hall until late in the evening.","The old bridge shook slightly each time a heavy lorry crossed it.","Heavy snow closed the mountain road for the third time that winter.","She poured two cups of mint tea and carried them onto the balcony."],"gapDistractors":[{"contextId":"u5_44_obtain_gap_1","answer":"obtain","wrong":["repair","widen","invent"]},{"contextId":"u5_44_obtain_gap_2","answer":"obtain","wrong":["burn","spill","pour"]},{"contextId":"u5_44_obtain_gap_3","answer":"obtain","wrong":["unfold","predict","calm"]}],"spellingErrors":["obtane","optain","obtian","abtain","obtaine","obtayn"],"masteryPassages":[{"passageId":"u5_44_obtain_passage_1","contextId":"u5_44_obtain_gap_1","text":"Last summer my sister planned a month of volunteer work in Peru. Before she could leave, she had to ____ a visa, a medical certificate and a letter from the charity, and that took nearly three weeks.","answer":"obtain"},{"passageId":"u5_44_obtain_passage_2","contextId":"u5_44_obtain_gap_2","text":"Every journalist at the festival needed a special pass to enter the main hall. The press office asked reporters to ____ their passes in person on the first morning and to bring a photograph.","answer":"obtain"}],"contextDependentParaphrases":[],"wrongParaphrases":["postpone","withdraw","replace"],"misleadingDistractors":["to pay for something in a shop","to refuse something that is offered","to lose something and look for it"],"teacherNote":"To get something officially or by making an effort (a visa, permission, information). It is not the same as buy, which means to pay for something."}]'::jsonb,'[]'::jsonb,'["obtain permission","obtain a visa","obtain information"]'::jsonb,'live'),
('vocab_specialise','specialise','verb','to focus your work or study on one particular area and become an expert in it','[{"senseId":"specialise_1","meaning":"to focus your work or study on one particular area and become an expert in it","acceptedParaphrases":["become an expert","focus on one area"],"masteryContexts":[{"contextId":"u5_45_specialise_meaning","text":"After a general degree in geography, she decided to specialise in sustainable tourism.","meaning":"to focus on one particular area of study or work","wrongMeanings":["to move from one area of study or work to another","to give up an area of study or work completely","to compare different areas of study or work"]},{"contextId":"u5_45_specialise_paraphrase","text":"Some tour operators prefer to specialise in a single region, so that their guides know it extremely well.","meaning":"to concentrate on one area and become an expert in it","wrongMeanings":["to avoid one area and become bored with it","to move to one area and become tired of it","to complain about one area and refuse to study it"]}],"situationDistractors":["A small boat rocked gently beside the stone steps of the harbour.","The shop assistant wrapped the glass vase in layers of paper.","It rained all morning, so the picnic was moved to the village hall.","Rain drummed on the tin roof of the bus shelter all afternoon.","The twins painted a picture of their grandmother’s garden for the school exhibition.","A line of camels walked slowly across the dune at sunset."],"gapDistractors":[{"contextId":"u5_45_specialise_gap_1","answer":"specialise","wrong":["hesitate","celebrate","separate"]},{"contextId":"u5_45_specialise_gap_2","answer":"specialise","wrong":["recover","escape","complain"]},{"contextId":"u5_45_specialise_gap_3","answer":"specialise","wrong":["believe","succeed","participate"]}],"spellingErrors":["specialize","specalise","speciallise","spesialise","specialice","specailise"],"wordFamilyForms":[{"form":"specialise","partOfSpeech":"verb","example":"Medical students may specialise in tropical medicine after three years of general study.","pedagogicallyUseful":true},{"form":"specialist","partOfSpeech":"noun","example":"A specialist in mountain rescue led the training session on the glacier.","pedagogicallyUseful":true,"altExample":"The hospital asked a specialist in tropical diseases to examine the returning traveller."},{"form":"specialisation","partOfSpeech":"noun","example":"Her main area of specialisation is marine biology, and she has worked on coral reefs for ten years.","pedagogicallyUseful":true,"altExample":"After a general course, students may choose a specialisation such as adventure tourism or event planning."}],"masteryPassages":[{"passageId":"u5_45_specialise_passage_1","contextId":"u5_45_specialise_gap_1","text":"Maya loves mountains, so after finishing school she took a course in outdoor leadership. In her second year she chose to ____ in winter sports, and now she trains ski instructors.","answer":"specialise"},{"passageId":"u5_45_specialise_passage_2","contextId":"u5_45_specialise_gap_2","text":"A large travel company can sell hundreds of different holidays. A small firm cannot compete in this way, so many small firms decide to ____ and become known for one particular kind of trip.","answer":"specialise"}],"contextDependentParaphrases":[],"wrongParaphrases":["change to a new job","take a long break","move to a new town"],"misleadingDistractors":["to travel to many different countries in a short time","to avoid doing a job that is difficult","to teach a subject to a large group of students"],"teacherNote":"British spelling (-ise). Taught with “in”: specialise in + subject. Students often write the American spelling."}]'::jsonb,'["specialist","specialisation"]'::jsonb,'["specialise in tourism","specialise in one region","specialise in adventure travel"]'::jsonb,'live'),
('vocab_qualification','qualification','noun','an official certificate or achievement, such as a diploma or an exam result, that shows you have the training or ability to do a job','[{"senseId":"qualification_1","meaning":"an official certificate or achievement, such as a diploma or an exam result, that shows you have the training or ability to do a job","acceptedParaphrases":["certificate","proof of training"],"masteryContexts":[{"contextId":"u5_46_qualification_meaning","text":"Without a qualification in diving, you cannot work as an instructor at a dive school.","meaning":"an official certificate showing that someone has the training for a job","wrongMeanings":["an official letter showing that someone has paid for a holiday","an official card showing that someone is allowed to enter a country","an official list showing that someone has booked a table"]},{"contextId":"u5_46_qualification_paraphrase","text":"Maria has a degree in hospitality, which is an important qualification for anyone who wants to manage a hotel.","meaning":"an achievement, such as a degree, that shows someone is able to do a job","wrongMeanings":["a prize, such as a medal, that shows someone is popular with tourists","a reward, such as a bonus, that shows someone has worked extra hours","a payment, such as a salary, that shows someone is employed by a company"]}],"situationDistractors":["The ferry horn sounded twice as the boat left the quay.","A group of cyclists stopped to fix a flat tyre beside the road.","On Sundays the market square is filled with stalls selling cheese and honey.","Waves broke over the rocks while gulls circled above the lighthouse.","Fresh paint was drying on the window frames of the little cottage.","An old man fed the pigeons in the square every morning."],"gapDistractors":[{"contextId":"u5_46_qualification_gap_1","answer":"qualification","wrong":["collection","invitation","decoration"]},{"contextId":"u5_46_qualification_gap_2","answer":"qualification","wrong":["complaint","accident","holiday"]},{"contextId":"u5_46_qualification_gap_3","answer":"qualification","wrong":["souvenir","timetable","departure"]}],"spellingErrors":["qualifiation","qualifcation","qualificashion","quallification","qualificaton","qualafication"],"wordFamilyForms":[{"form":"qualification","partOfSpeech":"noun","example":"A first-aid qualification is required for all guides at the centre.","pedagogicallyUseful":true},{"form":"qualify","partOfSpeech":"verb","example":"Guides must pass a practical exam in order to qualify as mountain leaders.","pedagogicallyUseful":true,"altExample":"It takes four years of study to qualify as a tour guide in some countries."},{"form":"qualified","partOfSpeech":"adjective","example":"Only qualified instructors are allowed to teach diving at the school.","pedagogicallyUseful":true,"altExample":"The agency employs fully qualified guides who speak at least two languages."}],"masteryPassages":[{"passageId":"u5_46_qualification_passage_1","contextId":"u5_46_qualification_gap_1","text":"Tom wanted to work as a scuba diving instructor on a Greek island. The dive school liked his enthusiasm, but it could only employ him once he had completed the exams and received a professional ____.","answer":"qualification"},{"passageId":"u5_46_qualification_passage_2","contextId":"u5_46_qualification_gap_2","text":"Applicants for the museum guide post are asked to list their education and experience. A degree in history is helpful, but an additional ____ in a foreign language is even more attractive to the employer.","answer":"qualification"}],"contextDependentParaphrases":[],"wrongParaphrases":["receipt","invitation","brochure"],"misleadingDistractors":["official permission to do something, usually shown on a card","a complaint made about the quality of a service","a meeting held to discuss a job application"],"teacherNote":"An official certificate or achievement (a diploma, a degree, an exam result) that shows training or ability. A licence, by contrast, is official permission to do something. Often used with “in” (a qualification in first aid) or “for” (a qualification for the job)."}]'::jsonb,'["qualify","qualified"]'::jsonb,'["a teaching qualification","a recognised qualification","qualification in first aid"]'::jsonb,'live'),
('vocab_evaluate_5','evaluate','verb','to judge the quality, value or success of something by studying evidence or using clear criteria','[{"senseId":"evaluate_5_1","meaning":"to judge the quality, value or success of something by studying evidence or using clear criteria","acceptedParaphrases":["weigh up","measure the success of"],"masteryContexts":[{"contextId":"u5_47_evaluate_5_meaning","text":"Before the new bus route was introduced, the council hired an expert to evaluate its effect on traffic and on local businesses.","meaning":"to judge the value or effect of something using evidence","wrongMeanings":["to ignore the value or effect of something despite the evidence","to increase the value or effect of something with advertising","to change the value or effect of something without evidence"]},{"contextId":"u5_47_evaluate_5_paraphrase","text":"At the end of the walk, the leader invited everyone to evaluate the route, the guide and the arrangements on a scale from one to five.","meaning":"to judge how good something is by using clear criteria","wrongMeanings":["to tell people how good something is by using clear slogans","to show how good something is by using clear photographs","to promise that something is good by using clear guarantees"]}],"situationDistractors":["A busker played the violin outside the station while commuters hurried past.","The children built a sandcastle and decorated it with shells.","Thick clouds covered the summit, so the climbers waited in the hut.","A cold drink and a rest in the shade were all the walkers wanted.","The shop sells postcards, stamps and maps of the surrounding hills.","Snow fell silently on the roofs of the little mountain village."],"gapDistractors":[{"contextId":"u5_47_evaluate_5_gap_1","answer":"evaluate","wrong":["repeat","delay","invite"]},{"contextId":"u5_47_evaluate_5_gap_2","answer":"evaluate","wrong":["borrow","applaud","forgive"]},{"contextId":"u5_47_evaluate_5_gap_3","answer":"evaluate","wrong":["postpone","decorate","translate"]}],"spellingErrors":["evalute","evaluat","evalaute","evaluete","evluate","evalueate"],"masteryPassages":[{"passageId":"u5_47_evaluate_5_passage_1","contextId":"u5_47_evaluate_5_gap_1","text":"After the first summer season, the new heritage trail had attracted ten thousand walkers. The council asked a team of researchers to ____ the project by counting visitors, interviewing local shop owners and checking the damage to the path.","answer":"evaluate"},{"passageId":"u5_47_evaluate_5_passage_2","contextId":"u5_47_evaluate_5_gap_2","text":"Teachers often ask students to compare two travel websites. The task is not simply to describe them; students have to ____ each one, deciding how clear, accurate and useful it is, and then explain their judgement.","answer":"evaluate"}],"contextDependentParaphrases":[],"wrongParaphrases":["pack away","hand over","look after"],"misleadingDistractors":["to repeat an activity many times to improve at it","to change something so that it looks better","to tell people that something is worth choosing"],"teacherNote":"Unit 5 item (evaluate_5), separate from Unit 3 evaluate; shares only the lexical spelling list. Sense: to judge quality, value or success using evidence or criteria. It is not the same as recommend, which says that something is worth choosing."}]'::jsonb,'[]'::jsonb,'["evaluate the results","evaluate the success of","carefully evaluate"]'::jsonb,'live'),
('vocab_itinerary','itinerary','noun','a detailed plan of a trip, showing the route and the places that will be visited','[{"senseId":"itinerary_1","meaning":"a detailed plan of a trip, showing the route and the places that will be visited","acceptedParaphrases":["travel plan","day-by-day programme"],"masteryContexts":[{"contextId":"u5_48_itinerary_meaning","text":"Our itinerary included two nights in Lisbon, a day trip to the coast and a morning at the national tile museum.","meaning":"a detailed plan of a trip showing places and times","wrongMeanings":["a detailed bill for a trip showing prices and taxes","a detailed report on a trip showing problems and complaints","a detailed map of a town showing streets and shops"]},{"contextId":"u5_48_itinerary_paraphrase","text":"The tour leader read out the itinerary on the coach so that everybody knew what to expect on the first morning.","meaning":"the planned route and list of places to visit on a journey","wrongMeanings":["the final cost and list of items to pay for on a holiday","the weather forecast and list of clothes to pack for a holiday","the safety rules and list of things to avoid on a mountain"]}],"situationDistractors":["The waiter brought a basket of warm bread and a bowl of olives.","The lighthouse keeper polished the lamp every evening before sunset.","Cold water splashed over the bow of the little fishing boat.","The old woman waved from her balcony as the parade passed by.","Torches lit the path to the cave entrance.","The pupils lined up in pairs outside the museum gates."],"gapDistractors":[{"contextId":"u5_48_itinerary_gap_1","answer":"itinerary","wrong":["invoice","receipt","passport"]},{"contextId":"u5_48_itinerary_gap_2","answer":"itinerary","wrong":["luggage","sandwich","sunburn"]},{"contextId":"u5_48_itinerary_gap_3","answer":"itinerary","wrong":["dictionary","postcard","sandwich"]}],"spellingErrors":["itinerery","itenerary","itinary","itineray","itinirary","itinerory"],"masteryPassages":[{"passageId":"u5_48_itinerary_passage_1","contextId":"u5_48_itinerary_gap_1","text":"Our class trip to London lasted four days. On the first evening, the teacher gave out a printed ____ which listed every museum, meal and train that we would use, so nobody was surprised.","answer":"itinerary"},{"passageId":"u5_48_itinerary_passage_2","contextId":"u5_48_itinerary_gap_2","text":"The travel agent spread a large map across her desk and began to plan a ten-day holiday for a family of four. She marked the route in red pen and then wrote out a day-by-day ____, leaving the final two days empty for rest.","answer":"itinerary"}],"contextDependentParaphrases":[],"wrongParaphrases":["holiday brochure","travel insurance","luggage label"],"misleadingDistractors":["a printed list of the times when trains and buses leave","a document that proves you have paid for a holiday","a short guide to the history of a town"],"teacherNote":"A countable noun: a detailed plan of a trip showing the route and the places to be visited. It is not the same as a timetable, which lists the times when buses or trains leave."}]'::jsonb,'[]'::jsonb,'["a detailed itinerary","plan an itinerary","follow the itinerary"]'::jsonb,'live'),
('vocab_safety_regulations','safety regulations','noun','official rules made by an authority to protect people from danger and injury','[{"senseId":"safety_regulations_1","meaning":"official rules made by an authority to protect people from danger and injury","acceptedParaphrases":["official protective rules","rules that protect people from harm"],"masteryContexts":[{"contextId":"u5_49_safety_regulations_meaning","text":"Hot-air balloon pilots need a licence, and under strict safety regulations the basket must be inspected every year.","meaning":"official rules designed to keep people from being hurt or put in danger","wrongMeanings":["official prices set to stop people from spending or saving too much money","official signs designed to help people to find or reach a place","official lists designed to show people which hotels are cheapest"]},{"contextId":"u5_49_safety_regulations_paraphrase","text":"The adventure park was closed for a week after inspectors found that it had broken several safety regulations.","meaning":"rules made by an authority to protect people from danger","wrongMeanings":["rules made by an authority to collect money from visitors","rules made by an authority to attract tourists to a region","rules made by an authority to reduce traffic in a town"]}],"situationDistractors":["The conductor stamped each ticket and walked down the swaying carriage.","A sudden gust of wind blew the menu off the café table.","Tourists queued patiently to buy ice cream on the promenade.","Pupils drew maps of the village for their geography project.","The ferry crossing took forty minutes and the sea was calm.","A drone hovered above the festival crowd, filming the dancers."],"gapDistractors":[{"contextId":"u5_49_safety_regulations_gap_1","answer":"safety regulations","wrong":["opening hours","ticket prices","dining customs"]},{"contextId":"u5_49_safety_regulations_gap_2","answer":"safety regulations","wrong":["school holidays","local customs","travel brochures"]},{"contextId":"u5_49_safety_regulations_gap_3","answer":"safety regulations","wrong":["holiday traditions","food prices","weather reports"]}],"spellingErrors":["safty regulations","safety regulashions","safety reglations","safetey regulations","saftey regulations","safety regulatons"],"masteryPassages":[{"passageId":"u5_49_safety_regulations_passage_1","contextId":"u5_49_safety_regulations_gap_1","text":"Before the first white-water rafting trip of the season, the guides met to go through the new rules. Every raft needed enough life jackets, every client had to wear a helmet and all guides had to be trained in rescue, because the national ____ now said so.","answer":"safety regulations"},{"passageId":"u5_49_safety_regulations_passage_2","contextId":"u5_49_safety_regulations_gap_2","text":"Many travellers think that a hot-air balloon flight is simply a matter of floating gently over the countryside. In fact, pilots must obey strict ____, including checks on wind speed and regular inspection of the basket.","answer":"safety regulations"}],"contextDependentParaphrases":[],"wrongParaphrases":["official travel documents","school holiday dates","tourist information leaflets"],"misleadingDistractors":["suggestions from experienced travellers about staying healthy","the notices that tell visitors the opening times","the instructions that explain how to use a machine"],"teacherNote":"A fixed noun phrase, normally plural: official rules made to keep people safe. Taught as a whole; Unit 4 teaches safety and regulation as separate words. Not the same as general advice, which nobody is required to follow."}]'::jsonb,'[]'::jsonb,'["strict safety regulations","follow safety regulations","break safety regulations"]'::jsonb,'live'),
('vocab_excursion','excursion','noun','a short organised trip, usually made for pleasure or education, from which people return the same day','[{"senseId":"excursion_1","meaning":"a short organised trip, usually made for pleasure or education, from which people return the same day","acceptedParaphrases":["day trip","organised outing"],"masteryContexts":[{"contextId":"u5_50_excursion_meaning","text":"The optional excursion to the island, a boat trip with a picnic lunch, costs extra and must be booked at the tour desk.","meaning":"a short organised trip that people take for pleasure","wrongMeanings":["long journeys that people make across several countries","free days that people spend resting at a hotel","tickets that people buy for entry to a museum"]},{"contextId":"u5_50_excursion_paraphrase","text":"Every Friday, the school organises an excursion to a farm, a factory or a museum, and the pupils write a report the next day.","meaning":"a short organised trip, usually for education","wrongMeanings":["a long and tiring journey, usually for work","a guided talk about an object, usually for children","a free afternoon, usually for shopping"]}],"situationDistractors":["The barista steamed the milk and drew a leaf in the foam.","Workmen repaired the tiles on the roof of the station.","An elderly couple sat on a bench and fed crumbs to the sparrows.","A street artist drew chalk pictures on the pavement near the fountain.","The fisherman mended his net on the quay, watched by a curious cat.","Rain had turned the football pitch into a muddy field."],"gapDistractors":[{"contextId":"u5_50_excursion_gap_1","answer":"excursion","wrong":["examination","exhibition","explanation"]},{"contextId":"u5_50_excursion_gap_2","answer":"excursion","wrong":["lesson","invoice","payment"]},{"contextId":"u5_50_excursion_gap_3","answer":"excursion","wrong":["rehearsal","argument","repair"]}],"spellingErrors":["excusion","excurtion","ecxursion","exkursion","excurshun","excurssion"],"masteryPassages":[{"passageId":"u5_50_excursion_passage_1","contextId":"u5_50_excursion_gap_1","text":"During our week in Seville, there were many free afternoons for exploring the old streets. The only organised activity was a full-day ____ to a sherry cellar in the countryside, which included lunch, a tasting and the coach ride home.","answer":"excursion"},{"passageId":"u5_50_excursion_passage_2","contextId":"u5_50_excursion_gap_2","text":"The geography teacher wanted her pupils to see a glacier with their own eyes, but a week in the mountains was too expensive. Instead she arranged a one-day ____ to a nearby ice cave, and the pupils were back in school by evening.","answer":"excursion"}],"contextDependentParaphrases":[],"wrongParaphrases":["rest day","school lesson","long holiday"],"misleadingDistractors":["a long and difficult journey to an unknown or dangerous place","a talk given by a guide who walks with a group around a building","a ticket that allows people to travel on any bus or train for a day"],"teacherNote":"A short organised trip, usually for pleasure or education, and normally returning the same day. Not an expedition (a long, difficult journey), not simply a journey, and not a guided tour of one building or site."}]'::jsonb,'[]'::jsonb,'["go on an excursion","a day excursion","an organised excursion"]'::jsonb,'live')
