('u5_42_equipment_5_meaning','vocab_equipment_5','u5_42_equipment_5','equipment_5_1','meaning_context','The kayak centre provides all the equipment you need, including helmets, paddles and life jackets.',null,'["kit"]'::jsonb,null,'live'),
