('u5_47_evaluate_5_gap_3','vocab_evaluate_5','u5_47_evaluate_5','evaluate_5_1','gap_fill','The inspectors visited the campsite to evaluate the quality of the food, the cleanliness and the condition of the showers.','evaluate','["evaluate"]'::jsonb,null,'live'),
('u5_48_itinerary_meaning','vocab_itinerary','u5_48_itinerary','itinerary_1','meaning_context','The tour company sent us a detailed itinerary showing where we would stay each night.',null,'["travel plan"]'::jsonb,null,'live'),
