('u5_48_itinerary_gap_1','vocab_itinerary','u5_48_itinerary','itinerary_1','gap_fill','The itinerary for the first day includes a visit to the castle, lunch in the old town and an evening boat trip.','itinerary','["itinerary"]'::jsonb,null,'live'),
('u5_48_itinerary_gap_2','vocab_itinerary','u5_48_itinerary','itinerary_1','gap_fill','Before leaving, we sent a copy of our itinerary to my parents, so they would know where we were each night.','itinerary','["itinerary"]'::jsonb,null,'live'),
('u5_48_itinerary_gap_3','vocab_itinerary','u5_48_itinerary','itinerary_1','gap_fill','A well-planned itinerary leaves free time for rest, because trying to see too much in a week is exhausting.','itinerary','["itinerary"]'::jsonb,null,'live'),
('u5_49_safety_regulations_meaning','vocab_safety_regulations','u5_49_safety_regulations','safety_regulations_1','meaning_context','Tour operators must obey strict safety regulations when they take tourists on mountain tracks.',null,'["official protective rules"]'::jsonb,null,'live'),
